struct Trie;
vector<Trie> heap;
struct Trie {
    int child_index = -1;
    void add(int depth)
    {
        if (depth == 0)
            return;
        if (child_index == -1) {
            child_index = heap.size();
            heap.push_back(Trie());
        }
        heap[child_index].add(depth-1);
    }
